mapper.update:
update task set
       title = #{title}, description=#{description}, status=#{status}, updated_at=Now() WHERE
       task_id=#{taskId}

mapper.select:
SELECT task_id, title, description, status, created_by, created_at, updated_at, deleted FROM
task WHERE deleted = false AND title LIKE '%' || #{keyword} || '%' AND status = #{status}
ORDER BY task_id ASC
